    /// <summary>
    /// MPJ-21310
    /// Check if substitutions (extended functionality) should be applied to this line.
    /// </summary>
    /// <returns>True if subs enabled</returns>
    public boolean metSubstitutionsActive()
    {
        boolean         ret = true;
        SalesTable      salesTable = this.salesTable();

        if(!salesTable.custTable_CustAccount().METSalesItemSubstitutionEnabled)
        {
            ret = false;
        }

        // TODO - Dependency on pending 'sales type' modification. Check 'substitutes enabled' flag.
        return ret;
    }

/// <summary>
/// Find corresponding METSalesLine (additional fields).
/// </summary>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>METSalesLine</returns>
public METSalesLine metSalesLine(boolean _forUpdate = false)
{
    return METSalesLine::find(this.RecId, _forUpdate);
}

    /// <summary>
    /// Get InventTable buffer related to the SalesLine with limited fields
    /// </summary>
    /// <returns>InventTable buffer with limited fields</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public InventTable metInventTableLimitedFields()
    {
        InventTable     metInventTableLimitedFields;
        select firstonly Product, NetWeight, TaraWeight, UnitVolume
            from metInventTableLimitedFields
            where metInventTableLimitedFields.ItemId == this.ItemId;

        return metInventTableLimitedFields;
    }

    /// <summary>
    /// Get MetItemSiteSettingsSetup buffer related to the SalesLine with limited fields
    /// </summary>
    /// <returns>METItemSiteSettingsSetup buffer with limited fields</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public MetItemSiteSettingsSetup metItemSiteSettingsSetupLimitedFields()
    {
        MetItemSiteSettingsSetup    metItemSiteSettingsSetupLimitedFields;
        InventSiteId                metInventSiteId = this.inventDim().InventSiteId;

        select firstonly ItemType, FilterCode1
            from metItemSiteSettingsSetupLimitedFields
            where metItemSiteSettingsSetupLimitedFields.ItemId == this.ItemId
            && metItemSiteSettingsSetupLimitedFields.InventSiteId == metInventSiteId;

        return metItemSiteSettingsSetupLimitedFields;
    }

/// <summary>
/// Get Metcash item type for item on the SalesLine.
/// </summary>
/// <returns>Metcash item type</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METItemTypes displayMETItemType()
{
    return this.metItemSiteSettingsSetupLimitedFields().ItemType;
}

/// <summary>
/// Get Order split category code for item on the SalesLine.
/// </summary>
/// <returns>Order split category code</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METOSCCode displayMETOSCCode()
{
    return ReqItemTable::find(this.ItemId, this.displayMETInventDimOSCCode().inventDimId).METOSCCode;
}

    /// <summary>
    /// Get InventDim for Site & Warehouse on SalesLine.
    /// </summary>
    /// <returns>Record of type InventDim</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display InventDim displayMETInventDimOSCCode()
    {
        InventDim   metInventDimOSCCode;

        metInventDimOSCCode.InventSiteId        = this.inventDim().InventSiteId;
        metInventDimOSCCode.InventLocationId    = this.inventDim().InventLocationId;

        metInventDimOSCCode = InventDim::findOrCreate(metInventDimOSCCode);

        return metInventDimOSCCode;
    }

/// <summary>
/// To get grossWeight for the SalesLine Item.
/// </summary>
/// <returns>GrossWeight of salesLine Item</returns>
[SysClientCacheDataMethodAttribute(true)]
public display ItemGrossWeight displayMETGrossWeight()
{
    return (this.SalesQty * (UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(this.SalesUnit).RecId,UnitOfMeasure::findBySymbol(METConstants::unitEach).RecId,this.metInventTableLimitedFields().Product).Factor) * (this.metInventTableLimitedFields().NetWeight + this.metInventTableLimitedFields().TaraWeight));
}

/// <summary>
/// To get unitVolume for the SalesLine Item.
/// </summary>
/// <returns>unitVolume of salesLine Item</returns>
[SysClientCacheDataMethodAttribute(true)]
public display ItemVolume displayMETUnitVolume()
{
    return (this.SalesQty * (UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(this.SalesUnit).RecId,UnitOfMeasure::findBySymbol(METConstants::unitEach).RecId,this.metInventTableLimitedFields().Product).Factor) * (this.metInventTableLimitedFields().UnitVolume));
}

/// <summary>
/// Calculate total number of cases for the sales order line quantity.
/// </summary>
/// <returns>Total cases of salesLine Item</returns>
[SysClientCacheDataMethod(true)]
public display InventQty metTotalcases()
{
    return this.SalesQty * roundUp(UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(this.SalesUnit).RecId,UnitOfMeasure::findBySymbol(METConstants::unitcase).RecId,this.metInventTableLimitedFields().Product).Factor,0);
}

/// <summary>
/// To calculate and display the number of cases for the sales order line quantity.
/// </summary>
/// <returns>Number of cases</returns>
[SysClientCacheDataMethod(true)]
public display METCase displayMETcases()
{
    return any2Int(this.metTotalcases());
}

/// <summary>
/// To calculate and display the number of broken cases for the sales order line quantity.
/// </summary>
/// <returns>Number of broken cases</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METBrokenCase displayMETBrokenCase()
{
    // If the sales order quantity is in a unit lower than case then convert the ordered quantity to case unit.
    // Broken case value is 0 if the units translate to a full case. Otherwise show Broken case as a
    // whole number (rounded up) if it's not a full case
    return frac(this.metTotalcases()) > 0 ? 1: 0;
}
